  ('4001 Series Clamping Servo to Shaft Coupler (24 Tooth Spline to 6mm Round Bore)', '4001-0024-0006', 'This coupler allows you to fasten a 6mm diameter shaft in-line with the output spline of a servo. The clamping feature insures that the shaft will not slip and it''s non-marring which means you can install and remove the shaft time and time again.', 'goBILDA', null, true, 'https://www.gobilda.com/4001-series-clamping-servo-to-shaft-coupler-24-tooth-spline-to-6mm-round-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/603/images/3677/4001-0024-0006-Patented__98253__29403.1701991972.386.513.jpg?c=1', null, 'gobilda'),
  ('4001 Series Clamping Servo to Shaft Coupler (25 Tooth Spline to 6mm Round Bore)', '4001-0025-0006', 'This coupler allows you to fasten a 6mm diameter shaft in-line with the output spline of a servo. The clamping feature ensures that the shaft will not slip, and it''s non-marring, which means you can remove and install this coupler as many times as you need.', 'goBILDA', null, true, 'https://www.gobilda.com/4001-series-clamping-servo-to-shaft-coupler-25-tooth-spline-to-6mm-round-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/604/images/3686/4001-0025-0006_REV1-Patented__37895__34664.1701991975.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
  ('4001 Series Clamping Servo to Shaft Coupler (25 Tooth Spline to 8mm REX® Bore)', '4001-0025-4008', 'This coupler allows you to fasten an 8mm REX® shaft in-line with the output spline of a servo. The clamping feature insures that the shaft will not slip and it''s non-marring which means you can install and remove the shaft time and time again.', 'goBILDA', null, true, 'https://www.gobilda.com/4001-series-clamping-servo-to-shaft-coupler-25-tooth-spline-to-8mm-rex-bore/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1453/images/7247/4001-0025-4008_Patented__08434__86495.1701993106.386.513.jpg?c=1', 'MOTION / Servos / Servo Attachments', 'gobilda'),
